import{_ as t,o as e,c as r,a0 as i}from"./chunks/framework.Bmhw_dvp.js";const u=JSON.parse('{"title":"弹幕系统","description":"","frontmatter":{},"headers":[],"relativePath":"features/danmaku.md","filePath":"features/danmaku.md","lastUpdated":1785820303000}'),l={name:"features/danmaku.md"};function d(o,a,h,n,s,b){return e(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="弹幕系统" tabindex="-1">弹幕系统 <a class="header-anchor" href="#弹幕系统" aria-label="Permalink to &quot;弹幕系统&quot;">​</a></h1><h2 id="功能概述" tabindex="-1">功能概述 <a class="header-anchor" href="#功能概述" aria-label="Permalink to &quot;功能概述&quot;">​</a></h2><p>弹幕是飘过视频画面的滚动文字评论，ZViewer 支持多种弹幕来源，让你在看番、看电影时感受到热闹的氛围。</p><hr><h2 id="多轨道弹幕聚合" tabindex="-1">多轨道弹幕聚合 <a class="header-anchor" href="#多轨道弹幕聚合" aria-label="Permalink to &quot;多轨道弹幕聚合&quot;">​</a></h2><p>ZViewer 支持同时加载多个视频源的弹幕并叠加显示。例如 B 站上同一部番剧可能有多个个人上传的版本，每个版本的弹幕是独立的，通过多轨道聚合功能，你可以将多个视频源的弹幕叠加在一起，实现弹幕翻倍的效果，让观影氛围更加热闹。</p><h2 id="弹幕的三个来源" tabindex="-1">弹幕的三个来源 <a class="header-anchor" href="#弹幕的三个来源" aria-label="Permalink to &quot;弹幕的三个来源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>来源</th><th>说明</th></tr></thead><tbody><tr><td>Bilibili 官方弹幕</td><td>从 Bilibili 拉取的原视频弹幕</td></tr><tr><td>DandanPlay 弹幕</td><td>第三方弹幕库，聚合多个来源</td></tr><tr><td>自定义弹幕</td><td>你和好友在房间内发送的实时弹幕</td></tr></tbody></table><h2 id="加载-bilibili-弹幕" tabindex="-1">加载 Bilibili 弹幕 <a class="header-anchor" href="#加载-bilibili-弹幕" aria-label="Permalink to &quot;加载 Bilibili 弹幕&quot;">​</a></h2><p>添加 Bilibili 视频后，弹幕会自动加载，从视频画面右向左飘过。</p><h2 id="发送自定义弹幕" tabindex="-1">发送自定义弹幕 <a class="header-anchor" href="#发送自定义弹幕" aria-label="Permalink to &quot;发送自定义弹幕&quot;">​</a></h2><p>在右侧面板的 <strong>「实时弹幕」Tab</strong> 中输入文字发送，所有观众都能看到。</p><h2 id="弹幕轨道管理" tabindex="-1">弹幕轨道管理 <a class="header-anchor" href="#弹幕轨道管理" aria-label="Permalink to &quot;弹幕轨道管理&quot;">​</a></h2><p>在 <strong>「弹幕轨道」Tab</strong> 中可屏蔽关键词、调整弹幕样式（字体/颜色/透明度/速度）、关闭某个弹幕轨道。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="弹幕不显示" tabindex="-1">弹幕不显示？ <a class="header-anchor" href="#弹幕不显示" aria-label="Permalink to &quot;弹幕不显示？&quot;">​</a></h3><p>确认视频已加载，检查弹幕轨道是否已加载，尝试重新添加视频。</p>',17)])])}const p=t(l,[["render",d]]);export{u as __pageData,p as default};
